// Lee el XML de cada factura y extrae los datos principales.
// Funciona con el formato DIAN: AttachedDocument con la factura adentro.

const P = '(?:[\\w-]+:)?'; // prefijo opcional (cbc:, cac:)
const reTag = n => new RegExp(`<${P}${n}(?:\\s[^>]*)?>([\\s\\S]*?)<\\/${P}${n}>`);
const reTagG = n => new RegExp(`<${P}${n}(?:\\s[^>]*)?>([\\s\\S]*?)<\\/${P}${n}>`, 'g');
const val = (x, n) => { const m = (x || '').match(reTag(n)); return m ? m[1].trim() : ''; };
const todos = (x, n) => [...(x || '').matchAll(reTagG(n))].map(m => m[1]);
const num = s => { const v = parseFloat(s); return isNaN(v) ? 0 : v; };
const redondear = v => Math.round(v * 100) / 100;

const decodificar = t => t
  .replace(/&lt;/g, '<').replace(/&gt;/g, '>')
  .replace(/&quot;/g, '"').replace(/&apos;/g, "'").replace(/&amp;/g, '&');

const esDocumento = t => new RegExp(`<${P}(Invoice|CreditNote|DebitNote)[\\s>]`).test(t);

// Saca la factura que viene "envuelta" dentro del AttachedDocument.
// Primero busca bloques CDATA completos; si no hay, prueba con texto escapado.
function facturaInterna(xml) {
  if (!new RegExp(`<${P}AttachedDocument[\\s>]`).test(xml)) return xml;
  for (const m of xml.matchAll(/<!\[CDATA\[([\s\S]*?)\]\]>/g)) {
    if (esDocumento(m[1])) return m[1];
  }
  for (const d of todos(xml, 'Description')) {
    const texto = decodificar(d.trim());
    if (esDocumento(texto)) return texto;
  }
  return xml;
}

// Número de factura: en el estándar DIAN va justo antes del CUFE (UUID).
// Si no lo encuentra, lo toma del asunto del correo (NIT;Nombre;Número;...).
function numeroFactura(encabezado, asunto) {
  const m = encabezado.match(new RegExp(`<${P}ID(?:\\s[^>]*)?>([^<]*)<\\/${P}ID>\\s*<${P}UUID`));
  if (m && m[1].trim()) return m[1].trim();
  const partes = (asunto || '').replace(/^(Fwd|RV|Fw|Re):\s*/i, '').split(';');
  if (partes.length >= 3 && partes[2].trim()) return partes[2].trim();
  return val(encabezado, 'ID');
}

function extraer(xmlCrudo, asunto, archivo) {
  const xml = xmlCrudo.replace(/^\uFEFF/, '');
  const interna = facturaInterna(xml);

  // Quita firmas/extensiones y líneas de detalle para leer solo los totales
  const doc = interna.replace(new RegExp(`<${P}UBLExtensions[\\s\\S]*?<\\/${P}UBLExtensions>`), '');
  const encabezado = doc.replace(new RegExp(`<${P}(InvoiceLine|CreditNoteLine|DebitNoteLine)[\\s>][\\s\\S]*?<\\/${P}\\1>`, 'g'), '');

  const tipoMatch = interna.match(new RegExp(`<${P}(Invoice|CreditNote|DebitNote)[\\s>]`));
  const tipos = { Invoice: 'Factura', CreditNote: 'Nota crédito', DebitNote: 'Nota débito' };

  const proveedor = val(encabezado, 'AccountingSupplierParty');
  const cliente = val(encabezado, 'AccountingCustomerParty');
  const totales = val(encabezado, 'LegalMonetaryTotal');

  // Impuestos del documento: 01 = IVA, 04 = INC
  let iva = 0, inc = 0, otros = 0;
  for (const t of todos(encabezado, 'TaxTotal')) {
    const monto = num(val(t, 'TaxAmount'));
    const codigo = val(val(t, 'TaxScheme'), 'ID');
    if (codigo === '01') iva += monto;
    else if (codigo === '04') inc += monto;
    else otros += monto;
  }

  let retenciones = 0;
  for (const w of todos(encabezado, 'WithholdingTaxTotal')) retenciones += num(val(w, 'TaxAmount'));

  const subtotal = num(val(totales, 'LineExtensionAmount'));
  const conImpuestos = num(val(totales, 'TaxInclusiveAmount'));
  const total = num(val(totales, 'PayableAmount'));

  // Control: subtotal + impuestos leídos debe dar el valor con impuestos de la factura.
  // Si la factura no trae ese valor, no se puede comparar y se da por bueno.
  const impuestosLeidos = iva + inc + otros;
  const cuadra = conImpuestos === 0 || Math.abs(subtotal + impuestosLeidos - conImpuestos) <= 1;

  return {
    estado: 'OK',
    tipo_documento: tipoMatch ? tipos[tipoMatch[1]] : 'Desconocido',
    numero: numeroFactura(encabezado, asunto),
    cufe: val(encabezado, 'UUID'),
    fecha_emision: val(encabezado, 'IssueDate'),
    proveedor: val(proveedor, 'RegistrationName'),
    nit_proveedor: val(proveedor, 'CompanyID'),
    cliente: val(cliente, 'RegistrationName'),
    nit_cliente: val(cliente, 'CompanyID'),
    moneda: val(encabezado, 'DocumentCurrencyCode'),
    subtotal: redondear(subtotal),
    iva: redondear(iva),
    inc: redondear(inc),
    otros_impuestos: redondear(otros),
    retenciones: redondear(retenciones),
    total: redondear(total),
    impuestos_cuadran: cuadra,
    archivo_xml: archivo,
    correo_asunto: asunto || '',
    procesado_en: new Date().toISOString()
  };
}

// ---- Recorre cada correo ----
const resultados = [];
const items = $input.all();

for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const binarios = item.binary || {};

  let correo = {};
  try { correo = $('Gmail · Recibir Facturas').itemMatching(i).json; } catch (e) { correo = item.json || {}; }

  const clave = Object.keys(binarios).find(k =>
    (binarios[k].fileExtension || '').toLowerCase() === 'xml' ||
    (binarios[k].fileName || '').toLowerCase().endsWith('.xml')
  );

  if (!clave) {
    resultados.push({ json: { estado: 'ERROR', detalle: 'El ZIP no trae XML', correo_asunto: correo.subject || '' } });
    continue;
  }

  try {
    const buffer = await this.helpers.getBinaryDataBuffer(i, clave);
    const datos = extraer(buffer.toString('utf-8'), correo.subject, binarios[clave].fileName);
    resultados.push({ json: datos });
  } catch (e) {
    resultados.push({ json: { estado: 'ERROR', detalle: 'No se pudo leer el XML: ' + e.message, correo_asunto: correo.subject || '' } });
  }
}

return resultados;

// Compara las facturas nuevas contra la hoja y marca alertas.

const facturas = $('Code · Extraer Datos Factura').all().map(i => i.json);
const filas = $input.all().map(i => i.json).filter(f => f && f.cufe);

const cufesVistos = new Set(filas.map(f => String(f.cufe)));
const historial = {}; // NIT -> lista de totales
for (const f of filas) {
  const nit = String(f.nit_proveedor || '');
  if (!historial[nit]) historial[nit] = [];
  historial[nit].push(Number(f.total) || 0);
}

const pesos = v => '$' + Math.round(v).toLocaleString('es-CO');
const resultados = [];

for (const f of facturas) {
  const alertas = [];

  if (f.estado !== 'OK') {
    resultados.push({ json: { ...f, alertas: 'ERROR DE LECTURA: ' + (f.detalle || ''), duplicada: true, tiene_alertas: true } });
    continue;
  }

  const nit = String(f.nit_proveedor || '');
  const duplicada = cufesVistos.has(String(f.cufe));
  if (duplicada) alertas.push('DUPLICADA: esta factura ya estaba registrada');

  const previos = historial[nit] || [];
  if (!duplicada && previos.length === 0) alertas.push('PROVEEDOR NUEVO: primer registro de este NIT');

  if (!duplicada && previos.length >= 3) {
    const promedio = previos.reduce((a, b) => a + b, 0) / previos.length;
    if (promedio > 0 && f.total > promedio * 2) {
      alertas.push(`VALOR ATÍPICO: ${pesos(f.total)} vs promedio ${pesos(promedio)}`);
    }
  }

  if (f.impuestos_cuadran === false) {
    alertas.push('REVISAR IMPUESTOS: no cuadran con los totales de la factura');
  }

  // Registra esta factura para comparar con las siguientes del mismo lote
  cufesVistos.add(String(f.cufe));
  if (!duplicada) {
    if (!historial[nit]) historial[nit] = [];
    historial[nit].push(Number(f.total) || 0);
  }

  resultados.push({
    json: {
      ...f,
      alertas: alertas.join(' | '),
      duplicada,
      tiene_alertas: alertas.length > 0
    }
  });
}

return resultados;
